select s.id as id, s.category_id as categoryId, s.name as name, s.price as price, s.status as status, s.description as description, s.image as image, s.update_time as updateTime, c.name as categoryName from setmeal as s inner join category as c on s.category_id = c.id
and s.name like CONCAT('%', #{name}, '%')
and s.category_id = #{categoryId}
and s.status = #{status}
order by s.create_time desc

select * from setmeal


        and name like concat('%',#{name},'%')


        and category_id = #{categoryId}


        and status = #{status}
